{
  "verses": [
    {
      "chapter": 8,
      "text_ar": "دَعْنِي أَتَكَلَّمْ صَرَاحَةً. لِنَكُنْ كُرَمَاءَ وَلْنَتَعَلَّمْ مَا هُوَ السَّبَبُ أَلَا يَجِبُ عَلَيْهِ فِي تَذَكُّرِ أَيَّامِ سَعَادَتِهِ السَّابِقَةِ أَنْ يُجَنَّ فِي عَقْلِهِ؟",
      "verse": 6
    },
    {
      "chapter": 8,
      "text_ar": "مَنْ لَا يَرْتَبِكُ تَمَاماً رُؤْيَةً لِنَفْسِهِ هَكَذَا يَنْزَلِقُ إِلَى الشِّقْوَةِ وَالضَّرَبَاتِ؟ وَلَكِنْ دَعْنِي أَقْتَرِبُ مِنْهُ لِكَيْ أَجِدَ بِأَيِّ سَبَبٍ هُوَ هَكَذَا؟",
      "verse": 7
    },
    {
      "chapter": 8,
      "text_ar": "وَقَامَ بِلْدَدُ وَاقْتَرَبَ مِنِّي قَائِلاً: \"أَأَنْتَ أَيُّوبُ؟\" وَقَالَ: \"هَلْ قَلْبُكَ مَا زَالَ فِي حِفْظٍ جَيِّدٍ؟\"",
      "verse": 8
    },
    {
      "chapter": 8,
      "text_ar": "وَقُلْتُ أَنَا: \"لَمْ أَتَمَسَّكْ بِالأَشْيَاءِ الأَرْضِيَّةِ، بِمَا أَنَّ الأَرْضَ مَعَ كُلِّ مَنْ يَسْكُنُ فِيهَا غَيْرُ ثَابِتَةٍ. لَكِنَّ قَلْبِي يَتَمَسَّكُ بِالسَّمَاءِ، لأَنَّهُ لَيْسَ هُنَاكَ ضِيقٌ فِي السَّمَاءِ\".",
      "verse": 9
    },
    {
      "chapter": 8,
      "text_ar": "ثُمَّ عَادَ بِلْدَدُ وَقَالَ: \"نَحْنُ نَعْلَمُ أَنَّ الأَرْضَ غَيْرُ ثَابِتَةٍ، لأَنَّهَا تَتَغَيَّرُ حَسَبَ الْمَوْسِمِ. فَفِي أَوْقَاتٍ تَكُونُ فِي حَالَةِ سَلاَمٍ، وَفِي أَوْقَاتٍ أُخْرَى تَكُونُ فِي حَالَةِ حَرْبٍ. وَلَكِنَّنَا نَسْمَعُ عَنِ السَّمَاءِ أَنَّهَا ثَابِتَةٌ تَمَاماً\".",
      "verse": 10
    }
  ],
  "book_code": "TJOB"
}
